async function sample(list, label, resize) {
  const picked = list.slice(0, 6);
  let before = 0, webp = 0;
  for (const f of picked) {
    before += statSync(f).size;
    let img = sharp(f);
    if (resize) img = img.resize(resize, resize, { fit: 'inside', withoutEnlargement: true });
    const buf = await img.webp({ quality: 82 }).toBuffer();
    webp += buf.length;
  }
  const pct = (1 - webp / before) * 100;
  console.log(`${label}: ${picked.length} files`);
  console.log(`  before: ${(before / 1e6).toFixed(1)} MB   after webp: ${(webp / 1e6).toFixed(2)} MB   saving: ${pct.toFixed(0)}%`);
  return pct;
}

const pngPct = await sample(pngs, 'PNG (1024px, displayed at <=550)', 600);
const jpgPct = await sample(jpgs, 'JPG (72x72 thumbnails)', null);

const pngTotal = pngs.reduce((a, f) => a + statSync(f).size, 0);
const jpgTotal = jpgs.reduce((a, f) => a + statSync(f).size, 0);
const projected = pngTotal * (1 - pngPct / 100) + jpgTotal * (1 - jpgPct / 100);
console.log(`\nprojected across all ${files.length} files:`);
console.log(`  now:       ${((pngTotal + jpgTotal) / 1e6).toFixed(0)} MB`);
console.log(`  projected: ${(projected / 1e6).toFixed(0)} MB`);

